contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try transferring tokens from this test contract's balance to some recipient.
    // We assert that totalSupply never changes due to transfer, and if the transfer succeeded
    // then the sender's balance decreased by value and recipient's balance increased by value;
    // if it reverted then both balances and totalSupply remain as before.
    function run(address to, uint256 value) public payable {
        require(to != address(0));
        // read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeSenderBal = c.balanceOf(address(this));
        uint256 beforeRecBal = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, value) returns (bool ok) {
            // If returns, treat as not reverted; ok should be true per implementation but use it only for clarity
            reverted = !ok; // if returned false, treat as reverted for our rule
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterSenderBal = c.balanceOf(address(this));
        uint256 afterRecBal = c.balanceOf(to);

        // General rule:
        // - totalSupply is unchanged by transfer attempts
        // - if the call reverted: balances unchanged
        // - if the call did not revert: sender decreased by value and recipient increased by value
        assert(
            afterTotal == beforeTotal
            && (reverted
                ? (afterSenderBal == beforeSenderBal && afterRecBal == beforeRecBal)
                : (beforeSenderBal >= value && afterSenderBal + value == beforeSenderBal && afterRecBal == beforeRecBal + value))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a target address and a bool to set freeze
    function run(address target, bool freeze) public payable {
        require(target != address(0));
        // read owner and the frozen status before
        address owner = c.owner();
        bool before = c.frozenAccount(target);

        // attempt freezeAccount and record whether it reverted
        bool reverted;
        // we must call as msg.sender == address(this) (InvMutTest), which is NOT the owner
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.frozenAccount(target);

        // General property:
        // If the caller (this contract) is the owner, the call must not revert and frozenAccount[target] equals the requested value.
        // If the caller is not the owner, the call must revert and frozenAccount[target] must be unchanged.
        // Expressed without branching on owner (owner is observed):
        assert(
            (address(this) == owner && reverted == false && after == freeze)
            ||
            (address(this) != owner && reverted == true && after == before)
        );
    }

    // receive not needed but allowed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a target address and a bool to set freeze
    function run(address target, bool freeze) public payable {
        require(target != address(0));
        // observe current owner and frozen status
        address owner = c.owner();
        bool beforeFrozen = c.frozenAccount(target);

        // attempt freezeAccount and record whether it reverted
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool afterFrozen = c.frozenAccount(target);

        // General property:
        // - If this contract is the owner, call must succeed (not revert) and frozenAccount[target] equals requested value.
        // - If this contract is not the owner, call must revert and frozenAccount[target] remains unchanged.
        assert(
            (address(this) == owner && reverted == false && afterFrozen == freeze)
            ||
            (address(this) != owner && reverted == true && afterFrozen == beforeFrozen)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 burnAmount) public payable {
        require(caller != address(0));
        // read before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 ownerAddr = uint160(c.owner());
        address owner = address(uint160(ownerAddr));
        uint256 beforeOwnerBal = c.balanceOf(owner);

        bool reverted;
        // Attempt burn as caller: since this contract is the msg.sender for calls to c,
        // we simulate calls by relying on the fact that only c.owner() equals this contract
        // when owner == address(this). If caller equals owner, we want the call to succeed,
        // otherwise it should revert. To model arbitrary caller, we perform the call only
        // when caller == owner by branching on that condition here (branching is allowed
        // in the test contract). For the complementary case (caller != owner) we attempt
        // a call that should revert by using the public burn function (msg.sender is this contract)
        // so we first check which scenario we are testing.

        if (caller == owner) {
            // We need to perform the burn as owner. The only way for this contract to be owner
            // is if c.owner() == address(this). The condition caller==owner enforces that.
            // Call burn and capture revert state.
            try c.burn(burnAmount) returns (bool ok) { reverted = false; } catch { reverted = true; }
            // After call, read values
            uint256 afterTotal = c.totalSupply();
            uint256 afterOwnerBal = c.balanceOf(owner);
            // If it reverted, then balances and totalSupply must be unchanged; if not reverted,
            // both owner balance and totalSupply must have decreased by the same amount (or equal
            // to zero behavior is naturally handled by uint arithmetic and require in burn)
            assert(reverted == false ? (afterTotal + 0 == beforeTotal - (reverted ? 0 : burnAmount) ? (afterOwnerBal + 0 == beforeOwnerBal - burnAmount) : false) : (afterTotal == beforeTotal && afterOwnerBal == beforeOwnerBal));
        } else {
            // caller != owner: calling burn from this contract (which is not owner) must revert and leave state unchanged
            try c.burn(burnAmount) returns (bool ok) { reverted = false; } catch { reverted = true; }
            uint256 afterTotal = c.totalSupply();
            uint256 afterOwnerBal = c.balanceOf(owner);
            assert(reverted == true && afterTotal == beforeTotal && afterOwnerBal == beforeOwnerBal);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // read owner and before-values
        address owner = c.owner();
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeOwnerBal = c.balanceOf(owner);

        // Attempt burn as this contract (msg.sender == address(this))
        bool reverted;
        try c.burn(burnAmount) returns (bool ok) { reverted = false; } catch { reverted = true; }

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterOwnerBal = c.balanceOf(owner);

        // General rule as a single assert:
        // If this contract is owner, burn must not revert and afterTotal == beforeTotal - burnAmount and afterOwnerBal == beforeOwnerBal - burnAmount.
        // If this contract is not owner, burn must revert and totals/balances unchanged.
        assert((address(this) == owner && reverted == false && afterTotal + burnAmount == beforeTotal && afterOwnerBal + burnAmount == beforeOwnerBal)
               || (address(this) != owner && reverted == true && afterTotal == beforeTotal && afterOwnerBal == beforeOwnerBal));
    }
    receive() external payable {}
}

