contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public function with all logic
    function run(address target, uint256 mintedAmount) public payable {
        // observe owner and before-values
        address owner = c.owner();
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeTargetBal = c.balanceOf(target);

        // attempt mintToken and record whether it reverted
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterTargetBal = c.balanceOf(target);

        // General rule as a single assert:
        // If this contract is the owner, mint must not revert and both totalSupply and target balance increase by mintedAmount.
        // If not owner, mint must revert and both values remain unchanged.
        assert((address(this) == owner && reverted == false && afterTotal == beforeTotal + mintedAmount && afterTargetBal == beforeTargetBal + mintedAmount)
               || (address(this) != owner && reverted == true && afterTotal == beforeTotal && afterTargetBal == beforeTargetBal));
    }
    receive() external payable {}
}
